<?php require dirname(__DIR__).'/config/config.php'; header('Content-Type: application/json; charset=utf-8'); try { $path=trim($_GET['resource']??'cacambas'); if($path==='cacambas'){ $s=db()->query('SELECT id,numero,tipo,status,localizacao FROM cacambas ORDER BY numero'); echo json_encode(['data'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE); } elseif($path==='clientes'){ $s=db()->query('SELECT id,nome,documento,email,telefone FROM clientes ORDER BY nome'); echo json_encode(['data'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE); } else { http_response_code(404); echo json_encode(['error'=>'Recurso não encontrado']); } } catch(Throwable $e){ http_response_code(500); echo json_encode(['error'=>'Erro interno']); }
